from pathlib import Path
p=Path('public/app.js');s=p.read_text(encoding='utf8')
def rep(a,b):
 global s
 assert a in s,a[:100]
 s=s.replace(a,b)
rep("const [data,seats]=await Promise.all([fetch('/candidaturas.json').then(r=>r.json()),fetch('/seats.json').then(r=>r.json())]);", "const [data,seats,groupConfig]=await Promise.all([fetch('/candidaturas.json').then(r=>r.json()),fetch('/seats.json').then(r=>r.json()),fetch('/statistical-groups.json').then(r=>r.json())]);\nconst displayGroups=new Map(groupConfig.groups.flatMap(g=>g.members.map(member=>[member,g.label])));\ndocument.querySelector('#resultados .filters').insertAdjacentHTML('beforeend','<label>Presentación de resultados<select id=\"result-grouping\"><option value=\"groups\">Agrupar por formación o coalición</option><option value=\"ballots\">Ver cada denominación electoral</option></select></label>');\ndocument.querySelector('#resultados .filters').insertAdjacentHTML('afterend','<details id=\"result-group-details\"><summary>Qué candidaturas suma cada grupo</summary><p>Se suman respuestas a denominaciones de una misma familia electoral. Por ejemplo, PSC-PSOE aparece como PSOE. Cada respuesta se cuenta una sola vez. Esta vista no transfiere votos ni presupone pactos. Las coaliciones mixtas conservan su identidad y no se reparten entre sus miembros.</p><div id=\"result-group-breakdown\"></div><p><a href=\"/statistical-groups.json\" target=\"_blank\">Consultar todas las equivalencias y sus fuentes ↗</a></p></details>');")
rep("responseLabel=id=>byId.has(id)?family(byId.get(id)):", "responseLabel=id=>byId.has(id)?($('result-grouping').value==='groups'?(displayGroups.get(family(byId.get(id)))||family(byId.get(id))):family(byId.get(id))):")
rep("$('total').textContent=fmt(total);", "const scopeParties=parties.filter(p=>(!$('region').value||p.region===$('region').value)&&(!$('province').value||p.province===$('province').value)),scopeNames=new Set(scopeParties.map(family));$('result-group-breakdown').innerHTML=groupConfig.groups.filter(g=>g.members.some(m=>scopeNames.has(m))).map(g=>{const breakdown=g.members.filter(m=>scopeNames.has(m)).map(member=>{const n=entries.filter(([id])=>byId.has(id)&&family(byId.get(id))===member).reduce((sum,[,n])=>sum+n,0);return esc(member)+' ('+fmt(n)+' respuestas)';});return '<p><strong>'+esc(g.label)+'</strong> ← '+breakdown.join(' + ')+'<br><span class=\"note\">'+esc(g.note)+'</span></p>';}).join('')||'<p>Las candidaturas de esta vista ya tienen denominaciones únicas.</p>';$('total').textContent=fmt(total);")
rep("$('province').onchange=renderResults;", "$('province').onchange=renderResults;$('result-grouping').onchange=renderResults;")
rep("methodology:'Muestra autoseleccionada; no representativa; sin ponderación.'", "grouping:$('result-grouping').value,groupDefinitions:groupConfig,methodology:'Muestra autoseleccionada; no representativa; sin ponderación.'")
p.write_text(s,encoding='utf8')
